effect.shader:
void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    float a = radians(angle);
    vec2 n = vec2(cos(a), sin(a));
    float t = dot(acScreenNorm - 0.5, n) + 0.5;
    float pos = fract(acTime * speed);
    float d = abs(t - pos);
    d = min(d, 1.0 - d);
    float faixa = smoothstep(width, 0.0, d);
    vec3 cor = orig.rgb + tint.rgb * faixa * gain * tint.a;
    fragColor = vec4(cor, orig.a);
}
